fn load(a: &[&str]) -> Result<Position, &'static str> {
    let mut p = Position {
        rights: 0,
    if a[2] != "-" {
        for c in a[2].bytes() {
            let i = b"KQkq".iter().position(|&x| x == c).ok_or("castling")?;
            p.rights |= 1 << i
    Ok(p)
    let initial = load(&[
        "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR",
        "w",
        "KQkq",
        "-",
        "0",
        "1",
    ])
    .unwrap();
    let mut p = initial.clone();
    let mut history: Vec<Record> = Vec::new();
